import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';

function EditProductForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState(null);

  useEffect(() => {
    const savedProducts = JSON.parse(localStorage.getItem('products')) || [];
    const prod = savedProducts.find(p => p.id === parseInt(id));
    if (prod) setProduct(prod);
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProduct(prev => ({ ...prev, [name]: value }));
  };

  const handleFile = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onloadend = () => setProduct(prev => ({ ...prev, image: reader.result }));
    if (file) reader.readAsDataURL(file);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const savedProducts = JSON.parse(localStorage.getItem('products')) || [];
    const updated = savedProducts.map(p => p.id === product.id ? product : p);
    localStorage.setItem('products', JSON.stringify(updated));
    navigate('/admin/products');
  };

  if (!product) return <p>Loading...</p>;

  return (
    <div className="card">
      <h2>Edit Product</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" name="name" placeholder="Product Name" value={product.name} onChange={handleChange} required />
        <input type="text" name="variation" placeholder="Variation" value={product.variation} onChange={handleChange} />
        <input type="number" name="price" placeholder="Price" value={product.price} onChange={handleChange} required />
        <textarea name="description" placeholder="Description" value={product.description} onChange={handleChange} />
        <input type="number" name="stocks" placeholder="Stocks" value={product.stocks} onChange={handleChange} required />
        <input type="file" onChange={handleFile} />
        <button type="submit">Update Product</button>
      </form>
    </div>
  );
}

export default EditProductForm;
